('21', '46', '19', '2', '3', '2', 'joomla/components', 'com_content', 'Components', 'components', '', '<p>Components are larger extensions that produce the major content for your site. Each component has one or more \"views\" that control how content is displayed. In the Joomla administrator there are additional extensions such as Menus, Redirection, and the extension managers.</p>', '1', NULL, NULL, '1', '{\"category_layout\":\"\",\"image\":\"\"}', '', '', '{\"author\":\"\",\"robots\":\"\"}', '502', '2022-12-28 09:11:11', '502', '2022-12-28 09:11:11', '0', '*', '1'),
('34', '59', '16', '12', '13', '2', 'sample-data-contact/park-site', 'com_contact', 'Park Site', 'park-site', '', '', '1', NULL, NULL, '1', '{\"target\":\"\",\"image\":\"\"}', '', '', '{\"page_title\":\"\",\"author\":\"\",\"robots\":\"\"}', '502', '2022-12-28 09:11:11', '502', '2022-12-28 09:11:11', '0', 'en-GB', '1'),
